def choose_approach(task, evals, volume_per_month, n_examples):
    """Return the cheapest approach that meets the bar on your own eval set."""
    bar = task.required_accuracy
    if evals["prompt"] >= bar:
        return "prompt"                          # cheapest, easiest to change
    if task.needs_facts and evals["rag"] >= bar:
        return "rag"                             # facts that change live in retrieval
    worth_tuning = volume_per_month >= 100_000 and n_examples >= 1_000
    if not worth_tuning:
        return "rag" if task.needs_facts else "prompt + better examples"
    if task.needs_facts:
        return "rag + fine-tuned model"          # tune behaviour, retrieve facts
    return "fine-tune"                           # format, style or a narrow skill

import json

def build_dataset(logged, checker, keep_rationale=True):
    """Keep teacher answers that pass checks; optionally keep their reasoning."""
    rows = []
    for r in logged:                              # {"query", "answer", "rationale"}
        if not checker(r["query"], r["answer"]):
            continue                              # filter out teacher mistakes
        target = (f"{r['rationale']}\nAnswer: {r['answer']}"
                  if keep_rationale else r["answer"])
        rows.append({"messages": [{"role": "user", "content": r["query"]},
                                  {"role": "assistant", "content": target}]})
    return rows

def route(query, student, teacher, threshold=0.8):
    """Serve from the student unless it is unsure."""
    answer, confidence = student(query)
    return answer if confidence >= threshold else teacher(query)

